#pragma once

#include <Arduino.h>
#include <SPI.h>
#include <RadioLib.h>

// ============================================================
// CC1101 - SENDER ONLY
// Exact Broadlink RM4 Pro RF codes from the supplied config
// Frequency: 433.92 MHz
// DATA/GDO0: GPIO3
// ============================================================

#define CC1101_DATA  3
#define CC1101_SCK   18
#define CC1101_MISO  16
#define CC1101_MOSI  17
#define CC1101_CS    1

static SPIClass cc1101SPI(FSPI);
static SPISettings cc1101SPISettings(2000000, MSBFIRST, SPI_MODE0);

static Module cc1101Module(
  CC1101_CS,
  CC1101_DATA,
  RADIOLIB_NC,
  RADIOLIB_NC,
  cc1101SPI,
  cc1101SPISettings
);

static CC1101 radio(&cc1101Module);

class ShutterControl {
public:
  enum ShutterId {
    Buero_Rollo,
    Schlafzimmer2,
    Schlafzimmer,
    Gaestezimmer_Rollo2,
    Kueche_Rollo1,
    Kueche_Rollo2,
    Bad_Rollo,
    Schlafzimmer_Rollo1,
    wz4,
    Wohnzimmer_Rollo_Tuer,
    Wohnzimmer_Rollo2,
    Wohnzimmer_Rollo3,
    Schlafzimmer1,
    Wohnzimmer
  };

private:
  struct CodeSet {
    const char* name;
    const char* open;
    const char* close;
    const char* stop;
  };

  static const CodeSet codes[];

  // Fahrzeiten aus der bisherigen Homebridge/Broadlink-Konfiguration.
  // Index entspricht ShutterId.
  static const uint32_t openDurationMs[];
  static const uint32_t closeDurationMs[];

  static uint32_t broadlinkUnitToUs(uint16_t unit) {
    return (uint32_t)((unit * 8192UL + 134) / 269UL);
  }

  bool sendBroadlinkCode(const char* hex) {
    if (!hex || strlen(hex) < 20) return false;

    const size_t hexLen = strlen(hex);
    if (hexLen & 1) return false;

    const size_t byteLen = hexLen / 2;

    auto nibble = [](char c) -> uint8_t {
      if (c >= '0' && c <= '9') return c - '0';
      if (c >= 'a' && c <= 'f') return c - 'a' + 10;
      if (c >= 'A' && c <= 'F') return c - 'A' + 10;
      return 0;
    };

    auto hexByte = [&](size_t pos) -> uint8_t {
      return (uint8_t)((nibble(hex[pos]) << 4) | nibble(hex[pos + 1]));
    };

    if (hexByte(0) != 0xB1 || hexByte(2) != 0xC0) {
      Serial.println("CC1101: kein B1C0-RF-Code");
      return false;
    }

    const uint16_t payloadLength =
      (uint16_t)hexByte(4) | ((uint16_t)hexByte(6) << 8);

    if ((size_t)payloadLength + 4 > byteLen || byteLen < 10) {
      Serial.println("CC1101: ungültiges Broadlink-Längenfeld");
      return false;
    }

    // B1C0:
    // 00..01 = marker
    // 02..03 = payload length, little endian
    // 04..07 = RF header
    // 08..   = alternating high/low timing values
    //
    // A value normally occupies one byte. If it is >255,
    // Broadlink stores 00 + 16-bit big-endian value.
    // 0005dc is the usual 1500-unit end gap.

    int16_t state = radio.transmitDirectAsync();

    if (state != RADIOLIB_ERR_NONE) {
      Serial.print("CC1101 TX Start Fehler: ");
      Serial.println(state);
      return false;
    }

    pinMode(CC1101_DATA, OUTPUT);
    digitalWrite(CC1101_DATA, LOW);

    size_t pos = 8;
    const size_t end = 4 + payloadLength;
    bool level = true;

    while (pos < end) {
      uint16_t unit;

      uint8_t b = hexByte(pos * 2);
      pos++;

      if (b == 0x00) {
        if (pos + 1 >= end) break;

        unit = ((uint16_t)hexByte(pos * 2) << 8) |
               hexByte(pos * 2 + 2);

        pos += 2;
      } else {
        unit = b;
      }

      const uint32_t us = broadlinkUnitToUs(unit);

      if (us == 0) {
        continue;
      }

      digitalWrite(CC1101_DATA, level ? HIGH : LOW);
      delayMicroseconds(us);

      level = !level;
    }

    digitalWrite(CC1101_DATA, LOW);
    delayMicroseconds(200);

    // Leave direct mode before anything else uses the CC1101.
    radio.packetMode();

    return true;
  }

public:
  void setup() {
    Serial.println();
    Serial.println("================================");
    Serial.println("CC1101 RADIOLIB TX SETUP");
    Serial.println("================================");
    Serial.println("Nur SENDEN - kein RX");
    Serial.println("CC1101 CS: GPIO1");

    pinMode(CC1101_DATA, OUTPUT);
    digitalWrite(CC1101_DATA, LOW);

    cc1101SPI.begin(
      CC1101_SCK,
      CC1101_MISO,
      CC1101_MOSI,
      CC1101_CS
    );

    int16_t state = radio.begin(
      433.92,
      512.0,
      5.0,
      650.0,
      10,
      16
    );

    Serial.print("RadioLib Init Status: ");
    Serial.println(state);

    if (state != RADIOLIB_ERR_NONE) {
      Serial.print("CC1101 INIT FEHLER: ");
      Serial.println(state);
      return;
    }

    Serial.println("CC1101: GEFUNDEN");

    state = radio.setOOK(true);
    Serial.print("OOK Status: ");
    Serial.println(state);

    radio.disableSyncWordFiltering();
    radio.setCrcFiltering(false);

    Serial.println("CC1101 bereit zum Senden.");
  }

  bool open(ShutterId id) {
    if ((int)id < 0 ||
        (int)id >= 14) {
      return false;
    }

    Serial.print("CC1101 OPEN: ");
    Serial.println(codes[id].name);

    return sendBroadlinkCode(codes[id].open);
  }

  bool close(ShutterId id) {
    if ((int)id < 0 ||
        (int)id >= 14) {
      return false;
    }

    Serial.print("CC1101 CLOSE: ");
    Serial.println(codes[id].name);

    return sendBroadlinkCode(codes[id].close);
  }

  bool stop(ShutterId id) {
    if ((int)id < 0 ||
        (int)id >= 14) {
      return false;
    }

    Serial.print("CC1101 STOP: ");
    Serial.println(codes[id].name);

    return sendBroadlinkCode(codes[id].stop);
  }

  uint32_t openDurationMsFor(ShutterId id) const {
    return openDurationMs[(int)id];
  }

  uint32_t closeDurationMsFor(ShutterId id) const {
    return closeDurationMs[(int)id];
  }

  const char* name(ShutterId id) const {
    return codes[id].name;
  }
};

